import{_ as i,c as r,o as n,ae as s}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Addressing Risks from Jenner & Block","description":"","frontmatter":{"title":"Addressing Risks from Jenner & Block","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/addressing-risks-from-jenner-block/","publishDate":"2025-03-25T16:18:38-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-25-addressing-risks-from-jenner-block.md","filePath":"executive-orders/2025-03-25-addressing-risks-from-jenner-block.md"}'),t={name:"executive-orders/2025-03-25-addressing-risks-from-jenner-block.md"};function a(o,e,l,c,d,g){return n(),r("div",null,e[0]||(e[0]=[s('<h1 id="addressing-risks-from-jenner-block" tabindex="-1">Addressing Risks from Jenner &amp; Block <a class="header-anchor" href="#addressing-risks-from-jenner-block" aria-label="Permalink to &quot;Addressing Risks from Jenner &amp; Block&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/addressing-risks-from-jenner-block/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/addressing-risks-from-jenner-block/</a></p><p>Published: Tuesday, March 25, 2025</p><ul><li>The Executive Order addresses risks associated with &quot;Big Law&quot; firms, particularly targeting those that engage in harmful conduct against American interests.</li><li>The Administration believes such firms threaten public safety, national security, constitutional freedoms, and the integrity of elections through their pro bono activities funded by client money.</li><li>Jenner &amp; Block LLP is specifically criticized for abandoning ethical standards and engaging in partisan lawfare, discriminatory practices, and supporting harmful political agendas.</li><li>It is stated that Jenner has rehired Andrew Weissmann, who has a controversial history of partisan prosecution and unethical behavior.</li></ul><p><strong>Key Directives:</strong></p><ul><li><p><strong>Security Clearances:</strong></p><ul><li>The Attorney General and heads of relevant agencies are instructed to suspend security clearances for individuals at Jenner pending a national interest review.</li></ul></li><li><p><strong>Government Materials and Services:</strong></p><ul><li>The Office of Management and Budget will identify and cease the provision of government goods or services to Jenner as permitted by law.</li></ul></li><li><p><strong>Contracting Practices:</strong></p><ul><li>Government contracting agencies must require disclosures from contractors regarding business with Jenner.</li><li>Agencies are to review contracts with Jenner and terminate them where permitted by law, aligning decisions with U.S. citizen interests.</li></ul></li><li><p><strong>Access Limitations:</strong></p><ul><li>Agencies are directed to limit access to federal buildings for Jenner employees if it threatens national security.</li><li>Guidance will restrict government employee interactions with Jenner employees, including Weissmann, without special waivers.</li></ul></li><li><p><strong>General Provisions:</strong></p><ul><li>The order does not limit other executive authority nor create legally enforceable rights against the U.S. or its entities.</li></ul></li><li><p>The order is to be implemented in accordance with the law and available funding.</p></li></ul>',6)]))}const p=i(t,[["render",a]]);export{h as __pageData,p as default};
